import React, { useState, useEffect } from 'react';
import { BarChart3, TrendingUp, Download, Filter, MoreVertical } from 'lucide-react';

const RevenueChart = () => {
  const [timeRange, setTimeRange] = useState('Mois');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Simuler le chargement des données
    const timer = setTimeout(() => setIsLoading(false), 1000);
    return () => clearTimeout(timer);
  }, []);

  const timeRanges = ['Jour', 'Semaine', 'Mois', 'Année'];

  // Données simulées pour le graphique
  const monthlyData = [
    { month: 'Jan', revenue: 12000 },
    { month: 'Fév', revenue: 19000 },
    { month: 'Mar', revenue: 15000 },
    { month: 'Avr', revenue: 22000 },
    { month: 'Mai', revenue: 28000 },
    { month: 'Jun', revenue: 32000 },
  ];

  const maxRevenue = Math.max(...monthlyData.map(d => d.revenue));

  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-xl sm:rounded-2xl p-4 sm:p-6 shadow-lg border border-white/30 dark:border-neutral-800/50 hover:shadow-xl transition-all duration-300 animate-fade-in">
      {/* En-tête avec contrôles */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <h3 className="text-lg sm:text-xl font-bold text-neutral-900 dark:text-white">
              Aperçu des revenus
            </h3>
            <TrendingUp className="h-5 w-5 text-accent-500 animate-bounce-subtle" />
          </div>
          <p className="text-sm text-neutral-600 dark:text-neutral-400">
            Performance des revenus au fil du temps
          </p>
        </div>

        <div className="flex items-center gap-2">
          {/* Sélecteur de plage de temps */}
          <div className="flex bg-neutral-100 dark:bg-neutral-800 rounded-lg p-1">
            {timeRanges.map((range) => (
              <button
                key={range}
                onClick={() => setTimeRange(range)}
                className={`px-3 py-1.5 text-sm rounded-md transition-all duration-300 ${
                  timeRange === range
                    ? 'bg-white dark:bg-neutral-700 text-primary-600 dark:text-primary-400 font-medium shadow-sm'
                    : 'text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-white'
                }`}
              >
                {range}
              </button>
            ))}
          </div>

          <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors duration-200">
            <Filter className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
          </button>
          <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors duration-200">
            <Download className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
          </button>
        </div>
      </div>

      {/* Graphique */}
      <div className="relative">
        {isLoading ? (
          <div className="h-64 flex items-center justify-center">
            <div className="text-center">
              <div className="w-12 h-12 border-3 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
              <p className="text-sm text-neutral-600 dark:text-neutral-400">
                Chargement des données...
              </p>
            </div>
          </div>
        ) : (
          <>
            {/* Légende */}
            <div className="flex items-center justify-end gap-4 mb-4">
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 bg-primary-500 rounded" />
                <span className="text-xs text-neutral-600 dark:text-neutral-400">
                  Revenus 2024
                </span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 bg-accent-500 rounded" />
                <span className="text-xs text-neutral-600 dark:text-neutral-400">
                  Objectif
                </span>
              </div>
            </div>

            {/* Graphique à barres */}
            <div className="h-64 relative">
              {/* Lignes de grille */}
              <div className="absolute inset-0 flex flex-col justify-between pb-10">
                {[0, 25, 50, 75, 100].map((percent, index) => (
                  <div
                    key={index}
                    className="border-t border-neutral-200 dark:border-neutral-700 relative"
                  >
                    <span className="absolute -left-12 -top-2 text-xs text-neutral-500 dark:text-neutral-500">
                      ${(maxRevenue * (percent / 100)).toLocaleString()}
                    </span>
                  </div>
                ))}
              </div>

              {/* Barres du graphique */}
              <div className="absolute inset-0 flex items-end justify-between px-8 pb-10 gap-4">
                {monthlyData.map((data, index) => {
                  const height = (data.revenue / maxRevenue) * 100;
                  return (
                    <div
                      key={data.month}
                      className="flex flex-col items-center flex-1 group"
                    >
                      <div className="relative w-full flex justify-center">
                        {/* Barre principale */}
                        <div
                          className="w-3/4 bg-gradient-to-t from-primary-500 to-primary-400 rounded-t-lg relative overflow-hidden transition-all duration-500 hover:scale-105 hover:w-4/5 cursor-pointer group-hover:from-primary-400 group-hover:to-primary-300"
                          style={{ height: `${height}%` }}
                        >
                          {/* Effet de brillance */}
                          <div className="absolute inset-0 bg-gradient-to-b from-white/20 to-transparent" />

                          {/* Tooltip */}
                          <div className="absolute -top-12 left-1/2 transform -translate-x-1/2 bg-neutral-900 text-white text-xs py-1 px-2 rounded opacity-0 group-hover:opacity-100 transition-opacity duration-300 whitespace-nowrap">
                            ${data.revenue.toLocaleString()}
                            <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-2 h-2 bg-neutral-900 rotate-45" />
                          </div>
                        </div>

                        {/* Barre d'objectif */}
                        <div
                          className="absolute w-3/4 h-1 bg-accent-500 rounded opacity-50 group-hover:opacity-100 transition-opacity duration-300"
                          style={{ bottom: '60%' }}
                        />
                      </div>

                      {/* Étiquette du mois */}
                      <span className="mt-2 text-xs text-neutral-600 dark:text-neutral-400 font-medium">
                        {data.month}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Statistiques en bas */}
            <div className="mt-8 pt-6 border-t border-neutral-200 dark:border-neutral-700">
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                <div className="text-center p-3 bg-neutral-50 dark:bg-neutral-800/50 rounded-lg">
                  <p className="text-sm text-neutral-600 dark:text-neutral-400">
                    Revenu moyen
                  </p>
                  <p className="text-lg font-bold text-neutral-900 dark:text-white">
                    $21,750
                  </p>
                </div>
                <div className="text-center p-3 bg-neutral-50 dark:bg-neutral-800/50 rounded-lg">
                  <p className="text-sm text-neutral-600 dark:text-neutral-400">
                    Croissance
                  </p>
                  <p className="text-lg font-bold text-accent-600 dark:text-accent-400">
                    +24.3%
                  </p>
                </div>
                <div className="text-center p-3 bg-neutral-50 dark:bg-neutral-800/50 rounded-lg">
                  <p className="text-sm text-neutral-600 dark:text-neutral-400">
                    Objectif
                  </p>
                  <p className="text-lg font-bold text-neutral-900 dark:text-white">
                    89%
                  </p>
                </div>
                <div className="text-center p-3 bg-neutral-50 dark:bg-neutral-800/50 rounded-lg">
                  <p className="text-sm text-neutral-600 dark:text-neutral-400">
                    Tendance
                  </p>
                  <p className="text-lg font-bold text-primary-600 dark:text-primary-400">
                    ↗ Positive
                  </p>
                </div>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default RevenueChart;
